                /**
                 * Převede číselnou hodnotu v B na stringovou hodnotu včetně jednotky (B, kB, MB, GB).
                 * @param {number} number Velikost v Bytech.
                 * @returns {string} Stringová velikost s jendotkou.
                 */
                prevedVelikostSouboruNaString(number) {
                    let stringRetVal = "";
                    if (number) {
                        if (number / (1024 * 1024 * 1024) >= 1) { //v GiB
                            stringRetVal = (+(Math.round(parseFloat(number / (1024 * 1024 * 1024) + "e+2")).toString() + "e-2")).toString() + " GB";
                        }
                        else if (number / (1024 * 1024) >= 1) { //v MiB
                            stringRetVal = (+(Math.round(parseFloat(number / (1024 * 1024) + "e+2")) + "e-2")).toString() + " MB";
                        }
                        else if (number / 1024 >= 1) { //v KiB
                            stringRetVal = (+(Math.round(parseFloat(number / 1024 + "e+2")) + "e-2")).toString() + " kB";
                        }
                        else { //v B
                            stringRetVal = number.toString() + " B";
                        }
                    }
                    else {
                        stringRetVal = "0 B";
                    }
                    return stringRetVal;
                }
