                prepareData(data) {
                    return new Gordic.Data.View(data, {
                        processors: {
                            typRevize: new Gordic.Data.ComputedFieldsProcessor((diff, rows) => {
                                for (var i = 0; i < rows.length; i++) {
                                    switch (rows[i].data.revize.substring(5, 6)) {
                                        case "0":
                                            rows[i].data.typRevize = "jres:33135264"; //RC 33135264 : Modul
                                            break;
                                        case "S":
                                            rows[i].data.typRevize = "jres:33135265"; //RC 33135265 : Sestavy
                                            break;
                                        case "H":
                                            rows[i].data.typRevize = "jres:33135266"; //RC 33135266 : Help
                                            break;
                                        case "D":
                                            rows[i].data.typRevize = "jres:33135267"; //RC 33135267 : Dokumentace
                                    }
                                }
                            }),
                            modul: new Gordic.Data.ComputedFieldsProcessor((diff, rows) => {
                                for (var i = 0; i < rows.length; i++) {
                                    var modulActual = rows[i].data.revize.substring(2, 5);
                                    rows[i].data.modul = modulActual;
                                }
                            })
                        }
                    });
                }
