                /**
                 * otevřít detail pro výběr balíku licencí generovaného licenčního certifikátu
                 */
                openDetailLicCertBalLic() {
                    var that = this;
                    var licDB = this.element.findFields("licenceDatabaze").gfield("getValue").lic_fyz;
                    that.isl.LicenceRadPID.listLicRadPIDBalLic({ filters: { lic: licDB } }).getData().then((data) => {
                        if (data.length > 1) {
                            var uniqueFieldLicenses = data
                                .map(item => item.ixs_lip + " - " + item.nazev)
                                .filter((value, index, self) => self.indexOf(value) === index);
                            Dpg.Dialogs.DetailLicCertBalLicDlg(this, { lic: licDB, dataRow: uniqueFieldLicenses }, Gordic.Gin.Globals.Enums.ModOtevreni.showModalWindow).then((data) => {
                                that.isl.PrehledLicenciDB.listLicencniCertifikaty({ filters: /*{ data:*/ { lic: licDB } /*}*/ }).getData().then((data) => {
                                    const view = new Gordic.Data.View(data, { key: "lic" });
                                    if (Gordic.Utils.WidgetExists("ggrid", that.gridLicCert)) { //nebo: if (that.grid1 != undefined) return   Podminka pro zjisteni, zda objekt ggrid existuje v promenne grid1
                                        that.viewLicCert.updateData(view.getDataRows());
                                        that.viewLicCert.requestData();
                                    }
                                });
                            });
                        }
                        else {
                            var selection = that.gridLicCert.ggrid("getView").getDataRows();
                            var uniqueFieldLicensePackages = selection
                                .map(item => item.ixs_lip + " - " + item.nazevBalLic)
                                .filter((value, index, self) => self.indexOf(value) === index);
                            if (uniqueFieldLicensePackages.length > 1) {
                                Dpg.Dialogs.DetailLicCertBalLicDlg(this, { lic: licDB, dataRow: uniqueFieldLicensePackages }, Gordic.Gin.Globals.Enums.ModOtevreni.showModalWindow).then((data) => {
                                    that.isl.PrehledLicenciDB.listLicencniCertifikaty({ filters: /*{ data:*/ { lic: licDB } /*}*/ }).getData().then((data) => {
                                        const view = new Gordic.Data.View(data, { key: "lic" });
                                        if (Gordic.Utils.WidgetExists("ggrid", that.gridLicCert)) { //nebo: if (that.grid1 != undefined) return   Podminka pro zjisteni, zda objekt ggrid existuje v promenne grid1
                                            that.viewLicCert.updateData(view.getDataRows());
                                            that.viewLicCert.requestData();
                                        }
                                    });
                                });
                            }
                            else {
                                if (uniqueFieldLicensePackages.length == 1) {
                                    that.dialogs.confirm("Licenční certifikát", "Přejete si vygenerovat nový licenční certifikát pro balík licencí " + selection[0].nazevBalLic + " ?", 650, 150).on("close", (ev, obj) => {
                                        if (obj === "yes") {
                                            that.ixs_lip = selection[0].ixs_lip;
                                            that.nazevBalLic = selection[0].nazevBalLic;
                                            that.actions.actNewCertPDF?.run();
                                        }
                                        else {
                                            return;
                                        }
                                    });
                                }
                                else {
                                    that.isl.LicenceRadPID.listLicRadPIDBalLic({ filters: { lic: licDB } }).getData().then((data) => {
                                        if (data.length > 1) {
                                            var uniqueFieldLicenses = data
                                                .map(item => item.ixs_lip + " - " + item.nazev)
                                                .filter((value, index, self) => self.indexOf(value) === index);
                                            Dpg.Dialogs.DetailLicCertBalLicDlg(this, { lic: licDB, dataRow: uniqueFieldLicenses }, Gordic.Gin.Globals.Enums.ModOtevreni.showModalWindow).then((data) => {
                                                that.isl.PrehledLicenciDB.listLicencniCertifikaty({ filters: /*{ data:*/ { lic: licDB } /*}*/ }).getData().then((data) => {
                                                    const view = new Gordic.Data.View(data, { key: "lic" });
                                                    if (Gordic.Utils.WidgetExists("ggrid", that.gridLicCert)) { //nebo: if (that.grid1 != undefined) return   Podminka pro zjisteni, zda objekt ggrid existuje v promenne grid1
                                                        that.viewLicCert.updateData(view.getDataRows());
                                                        that.viewLicCert.requestData();
                                                    }
                                                });
                                            });
                                        }
                                        else {
                                            if (data[0] != null && data[0] != undefined && data[0].ixs_lip != null && data[0].nazev != null) {
                                                that.ixs_lip = data[0].ixs_lip;
                                                that.nazevBalLic = data[0].nazev;
                                            }
                                            that.dialogs.confirm("Licenční certifikát", "Přejete si vygenerovat nový licenční certifikát pro balík licencí " + that.nazevBalLic + " ?", 650, 150).on("close", (ev, obj) => {
                                                if (obj === "yes") {
                                                    that.actions.actNewCertPDF?.run();
                                                }
                                                else {
                                                    return;
                                                }
                                            });
                                        }
                                    });
                                }
                            }
                        }
                    });
                }
