                /**
                 * vytvoři filtrPanel form
                 */
                createFilterForm() {
                    var that = this;
                    let filterForm = new Gordic.Forms.Form({
                        name: "formFilter",
                        tabLabel: "jres:33135007", //RC 33135007 : Kompletní filtr
                        layoutDescriptor: "L2M2S1, L-3-8-1, M-12-11-1, S-12-11-1, breaks-700-1000"
                    });
                    const dostupneLicenceOptions = {
                        name: "licenceDatabaze",
                        model: "lic_fyz=lic_fyz" /*; nazev = nazev; verze_db = verze_db; sub_verze_db = sub_verze_db; revize_adz = revize_adz"*/,
                        validators: [
                            new Gordic.Validators.Required(),
                            new Gordic.Validators.Length({ min: 4, max: 4, message: "jres:33135128" }) //RC 33135128 : Zadejte 4 znaky
                        ],
                        change: function (ev, changeObj) {
                            // Flag posílaný z filterpanelu.
                            if (changeObj.flags?.noChange || changeObj.flags?.isKontrolniDiv) {
                                return;
                            }
                            const field = $(that.element).findFields("verze");
                            if (Gordic.Utils.WidgetExists("gfield", field)) {
                                //field.gfield("model", "apply", changeObj.value)
                                field.gfield("setValue", changeObj.value);
                            }
                        },
                        initialValue: that.initialLicense,
                    };
                    //Osetreni pristupu - 5 = zakaznik, 0 = vlastni
                    if (that.UserParam == "5" || that.UserParam == "0") {
                        filterForm
                            .addSection()
                            .addRow({
                            label: "jres:33135193", //RC 33135193 : Licence databáze
                        })
                            .addField("gselectbox", Gordic.Prefabs.Select.dostupneLicenceIxsFun(), dostupneLicenceOptions, {
                            serverFilters: { ixs_fun: this.IxsFun },
                            validators: [new Gordic.Validators.Required()],
                        });
                    }
                    else {
                        filterForm
                            .addSection()
                            .addRow({
                            label: "jres:33135193", //RC 33135193 : Licence databáze
                        })
                            .addField("gselectbox", Gordic.Prefabs.Select.dostupneLicence(), dostupneLicenceOptions, {
                            validators: [new Gordic.Validators.Required()],
                        });
                    }
                    filterForm
                        .addRow({
                        label: "jres:33135218", //RC 33135218 : Aktuální verze databáze
                    })
                        .addField("gselectbox", Gordic.Prefabs.Select.dostupneVerzeRevize(), {
                        name: "verze",
                        model: "verze_db=verze_db;sub_verze_db=sub_verze_db",
                        customClass: "w-8",
                        validators: [new Gordic.Validators.Required()],
                    });
                    filterForm
                        .addRow({ label: "jres:33135221" }); //RC 33135221 : Fáze
                    filterForm
                        .addField("gselectbox", Gordic.Prefabs.Select.gDpgReaderFaze() /*Gordic.Prefabs.Select.gincfaz()*/, {
                        name: "faze",
                        customClass: "w-8",
                        model: "model.faze=value.faze",
                        serverFilters: {
                            faze_typ: "All"
                        },
                    });
                    filterForm
                        .addRow({});
                    filterForm
                        .addField("gcheck", {
                        name: "modul",
                        //labelFromRow: true,
                        label: "Modul",
                        customClass: "w-4",
                        initialValue: true,
                    })
                        .addField("gcheck", {
                        name: "sestavy",
                        //labelFromRow: true,
                        label: "Sestavy",
                        customClass: "w-4",
                        initialValue: true,
                    })
                        //filterForm
                        //	.addRow({})
                        //filterForm
                        //filterForm
                        //.addRow()
                        .addField("gcheck", {
                        name: "help",
                        //labelFromRow: true,
                        label: "Help",
                        customClass: "w-4",
                        initialValue: true,
                    });
                    filterForm
                        .addRow()
                        .addField("gcheck", {
                        name: "dokumentace",
                        //labelFromRow: true,
                        label: "Dokumentace",
                        customClass: "w-6",
                        initialValue: true,
                    });
                    if (that.UserParam != "5") { //Určeno pouze mimo uživatele typu Zákazník
                        filterForm
                            .addField("gcheck", {
                            name: "betatest",
                            label: "Betatest",
                            customClass: "w-4",
                            initialValue: false,
                            //tooltip: "jres:33135387" //RC 33135387 : Zahrnout nejvyšší revize ve stavu Betatest
                        });
                    }
                    return filterForm;
                }
