                /**
                 * vytvořit status bar
                 */
                createStatusBar() {
                    let statusbar = new Array({
                        type: "static",
                        icon: "gi-radio g-state-text g-state-active",
                        caption: "Seznam dostupných revizí",
                        customClass: "g-state-text g-state-active"
                    });
                    this.statusBar(statusbar);
                }
                /**
                 * vytvořit seznam
                 */
                createGrid() {
                    const that = this;
                    this.gridDoporuceneRevizeFormat = this.createGridFormat();
                    let columnNames = Dpg.GridUtils.getColumnsName(this.gridDoporuceneRevizeFormat);
                    this.gridDoporuceneRevize = $.newDiv().gautofit().appendTo(this.element);
                    this.gridDoporuceneRevize.ggrid({
                        multi: true,
                        data: this.view,
                        name: "gridSeznamBalicku",
                        renderMode: "auto", // auto, all-at-once, paged-sync, paged-async
                        columnMode: "full", // fit (defaultne by melo byt toto), full
                        customClass: "ts-grid-seznam-balicku-class",
                        navigationMode: "row", // row, cell
                        defaultAction: new GAction({
                            name: "doubleClickGridSeznamBalicku",
                            run: (ev, ctx) => {
                            }
                        }),
                        selection: (ev, obj) => {
                            that.enablePreviewZmeny(true);
                            var selection = that.gridDoporuceneRevize.ggrid("getSelection");
                            var sizeCounter = 0;
                            if (selection.length != 0) {
                                for (var i = 0; i < selection.length; i++) {
                                    sizeCounter = sizeCounter + selection[i].velikost;
                                }
                                var totalSize = that.prevedVelikostSouboruNaString(sizeCounter);
                                ////that.statusGrid[0].childNodes[0].nodeValue = "Celková velikost souborů označených ke stažení: "  /*+"<b class='g-state-text g-state-active'>"*/ + totalSize + /*"</b>" +*/ "";
                                that.statusGrid.html("Celková velikost souborů označených ke stažení: <b class='g-state-text g-state-active'>" + totalSize + "</b>");
                            }
                            else if (that.statusGrid != undefined) {
                                that.statusGrid.html("Celková velikost souborů označených ke stažení: <b class='g-state-text g-state-active'> 0 B </b>");
                            }
                            this.element.trigger("actualRow", { row: this.gridDoporuceneRevize.ggrid("activeRow") });
                            if (this.gridDoporuceneRevize.ggrid("activeRow")) {
                                that.previewController.show(/*ctx.cellInfo.data*/ obj.getSelection()[0]);
                                if (that.sidebarPanelZmenyCreated == false) {
                                    this.element.gsidebar("addPanel", "right", {
                                        minWidth: 300,
                                        id: "prehledZmen",
                                        icon: "gi-log-prohlizeni",
                                        caption: "jres:33135322", //RC 33135322 : Přehled změn v revizi 
                                        leaf: "jres:33135323", //RC 33135323 : Přehled změn
                                        open: (ev, obj) => {
                                            that.enablePreviewZmeny(true);
                                            that.loadPreviewZmeny();
                                        },
                                        customDiv: that.createPreviewDivZmeny(),
                                    });
                                    that.sidebarPanelZmenyCreated = true;
                                }
                                else if (that.sidebarPanelZmenyCreated == true) {
                                    //that.enablePreviewZmeny(true);
                                    that.loadPreviewZmeny();
                                }
                            }
                            that.endOperation();
                        },
                        cellActivate: function (ev, ctx) {
                            if (ctx != null && ctx.cellInfo != null && ctx.cellInfo.data != null) {
                                that.previewController.enable(true);
                                that.previewController.show(ctx.cellInfo.data);
                                that.enablePreviewZmeny(true);
                            }
                            else {
                                that.previewController.enable(false);
                                that.enablePreviewZmeny(false);
                            }
                        },
                        contextMenu: this.createContextBar(), //Kontextove manu na prave tlacitko mysi
                        searchColumns: columnNames,
                        defaultProfile: {
                            name: "defaultProfile",
                            columnList: [
                                gridColumnsNames.revize,
                                gridColumnsNames.typRevize,
                                gridColumnsNames.faze,
                                gridColumnsNames.stavFazeTxt,
                                gridColumnsNames.stav_stat,
                                gridColumnsNames.stav,
                                gridColumnsNames.minimalniPozadovanaVerzeDB,
                                gridColumnsNames.datZmena,
                                gridColumnsNames.velikost,
                            ].toString()
                        },
                        profiles: [
                            {
                                //Dalsi profil Pohledu
                                name: "extendedProfile",
                                columnList: [
                                    gridColumnsNames.revize,
                                    gridColumnsNames.modul,
                                    gridColumnsNames.typRevize,
                                    gridColumnsNames.faze,
                                    gridColumnsNames.stavFazeTxt,
                                    gridColumnsNames.stav_stat,
                                    gridColumnsNames.stav,
                                    gridColumnsNames.minimalniPozadovanaVerzeDB,
                                    gridColumnsNames.datZmena,
                                    gridColumnsNames.velikost,
                                ].toString()
                            },
                        ],
                        columns: this.gridDoporuceneRevizeFormat,
                    });
                }
                /**
                 * vytvořit kontextove menu z gridu na prave tlacitko mysi
                 */
