            /**
           * na akci změní property visibled - zobrazí nebo zneviditelní - pridano vblabla
           * @param Action
           * @param visible
           */
            function setActionVisible(Action, visible) {
                if (Action !== undefined) { // pokud neni undefined, proved update
                    if (!visible)
                        Action.update({ visible: false });
                    else
                        Action.update({ visible: true });
                }
            }
            Utils.setActionVisible = setActionVisible;
            /**
            * metoda, která zvaliduje formulář a vrátí výsledek validace až je formulář připraven
            *
            * @param {JQuery<HTMLElement>} form předaný element formuláře
            * @returns {JQueryPromise<boolean>} výsledek stavu
            */
            function waitForValues(form) {
                var dfd = $.Deferred();
                form.gform("waitForValues")
                    .then(() => {
                    return form.gform("isValid");
                })
                    .then((isValid) => {
                    dfd.resolve(isValid);
                })
                    .fail(() => {
                    dfd.reject(false);
                });
                return dfd.promise();
            }
            Utils.waitForValues = waitForValues;
